/* Per-frame check of the three moby groups linked from the hero's moby state. */
void process_hero_race_object_interactions(void) {
    u8 *state;
    u8 *first;
    u8 *second;
    u8 *third;
    float delta[4];
    float matrix[16];
    int *ap;
    int count, red, green, blue;
    float period, wave, ratio;

    if (HERO->hoverboard_moby == 0)
        return;
    state = *(u8 **)(HERO->hoverboard_moby + 0x78);
    if (*(int *)(state + 0x44) != -1) {
        get_first_moby_in_group((void **)&first, *(int *)(state + 0x44), 0, 0);
        if (first != 0) {
            do {
                if (((Moby *)first)->oclass == MOBY_CLASS_HOVERBOARD_RING &&
                    fast_subtract_rotations_cf(first + 0xBC) != 0) {
                    FastVecSub(delta, first + 0x10, (char *)hero_globals_base + 0xEED);
                    set_identity_matrix(matrix);
                    matrix_from_basis_rows(matrix, first + 0xC0);
                    transform_vector(delta, delta, matrix);
                    if (absolute_float(delta[0]) < 0.5f && absolute_float(delta[1]) < 2.9f &&
                        absolute_float(delta[2]) < 2.9f) {
                        HERO->boost_pad_timer += **(int **)(first + 0x78);
                        ((Moby *)first)->command = scale_ticks(0x3C);
                        if (HERO->hoverboard_moby != 0)
                            Moby_PlaySound(1, 0, (int)HERO->hoverboard_moby);
                    }
                }
                get_next_moby_in_group((void **)&first, first, 0, 0);
            } while (first != 0);
        }
    }
    count = scale_ticks(0x32);
    period = IntToFloat(count);
    ratio = (float)(*(int *)&rilgar_frame_count % count) / period;
    ratio += ratio;
    wave = FastSin(ratio * 3.1415927f + -3.1415927f);
    red = truncate_float_to_s32(wave * 48.0f) + 0x68;
    green = truncate_float_to_s32(wave * 64.0f) + 0xD0;
    blue = truncate_float_to_s32(wave * 24.0f) + 0x3C;
    if (green > 0xFF)
        green = 0xFF;
    if (*(int *)(state + 0x48) != -1) {
        if (HERO->hoverboard_airborne == 0) {
            get_first_moby_in_group((void **)&second, *(int *)(state + 0x48), 0, 0);
            if (second != 0) {
                unsigned int color = (blue << 16) | (0x80000000U | (green << 8)) | red;
                do {
                    if (((Moby *)second)->oclass == MOBY_CLASS_HOVERBOARD_BOOST_PAD) {
                        ((Moby *)second)->flags |= 0x10;
                        *(unsigned int *)(second + 0x90) = color;
                        if (fast_subtract_rotations_cf(second + 0xBC) != 0) {
                            FastVecSub(delta, second + 0x10, (char *)hero_globals_base + 0xE9D);
                            set_identity_matrix(matrix);
                            matrix_from_basis_rows(matrix, second + 0xC0);
                            transform_vector(delta, delta, matrix);
                            if (absolute_float(delta[0]) < 2.8f && absolute_float(delta[1]) < 1.25f &&
                                absolute_float(delta[2]) < 1.5f) {
                                HERO->boost_pad_timer += **(int **)(second + 0x78);
                                ((Moby *)second)->command = scale_ticks(0x3C);
                                if (HERO->hoverboard_moby != 0)
                                    Moby_PlaySound(1, 0, (int)HERO->hoverboard_moby);
                            }
                        }
                    }
                    get_next_moby_in_group((void **)&second, second, 0, 0);
                } while (second != 0);
            }
        }
    }
    if (*(int *)(state + 0x4C) != -1) {
        get_first_moby_in_group((void **)&third, *(int *)(state + 0x4C), 0, 0);
        if (third != 0) {
            ap = (int *)(menu_item_enabled_115 + 0x21);
            do {
                if (*(short *)(third + 0xA6) == 0x1D6 && fast_subtract_rotations_cf(third + 0xBC) != 0 &&
                    fast_vec_dist((char *)hero_globals_base + 0xEED, third + 0x10) < 1.5f) {
                    struct Hero *g = HERO;
                    third[0xBC] = scale_ticks(300);
                    if (*(int *)((u8 *)g + 0x10B8) != 0x24) {
                        *(int *)((u8 *)g + 0x20B8) = 0x24;
                        g->item_use_locked = 0;
                        apply_hero_item_slot_selection(0);
                        g->item_use_locked = 1;
                    }
                    g->race_ammo++;
                    if (g->race_ammo > 3)
                        g->race_ammo = 3;
                    *(int *)((u8 *)g + 0x20B8) = 0x24;
                    ap[36]++;
                }
                get_next_moby_in_group((void **)&third, third, 0, 0);
            } while (third != 0);
        }
    }
}
