        char *p = path + i * 16;
        float limit = 4.0f;
        float angle = fast_atan2(*(float *)(p + 0x10) - h->motion.pos.f[0], *(float *)(p + 0x14) - h->motion.pos.f[1]);
        int n2 = *(int *)path + 2;
